#include "stdafx.h"#include "Translator.h"#include <rsuErr.h>namespace ns_HcdTranslator{  eToken_value KHcdTranslator::GetToken( std::istream &input )  {    m_Value.clear();    eToken_value tok( etUnknown );    char ch = 0;    do     {      if(!input.get(ch))         return etEndInData;    }while( ch==' ' || ch=='\t' );    switch( ch )    {    case '?':      return etIF_POST;    case ':':      return etELSE;    case '\n':      tok = etEndLine;      break;    case etNE:      m_Value = ch;      tok = eToken_value(ch);      input.get(ch);      if( etEQ==ch )      {        m_Value += ch;      }      else      {        tok = etNOT;        input.unget();      }      break;    case etEQ:      m_Value = ch;      tok = eToken_value(ch);      input.get(ch);      if( etEQ==ch )      {        tok = etEQ;        m_Value += ch;      }      else      {        tok = etASSIGN;        input.unget();      }      break;    case etMINUS:      m_Value = ch;      switch( Parm.tokAfterAnalize )      {      case etLP:      case etASSIGN:        {          std::string v;          v = ch;          eToken_value n = GetToken( input );          ASSD( etNUMBER );          tok = n;          v += m_Value;          m_Value = v;          return tok;          KKK();        }        break;      }    case etBlockOpen:    case etBlockClose:    case etPLUS:    case etMUL:    case etDIV:    case etCOMMA://,    case etLP:    case etRP:    case etEndExpr://;      m_Value = ch;      tok = eToken_value(ch);      break;    case etBITOR:    case etBITAND:      m_Value = ch;      tok = eToken_value(ch);      {        char chN = 0;        input.get(chN);        if( ch!=chN )          input.unget();        else        {          m_Value += chN;          if( ch==etBITAND )            tok =etAND;          else if( ch==etBITOR )            tok =etOR;        }      }      break;    case etGT:    case etLT:      m_Value = ch;      tok = eToken_value(ch);      input.get(ch);      if( '='==ch )      {        switch(tok)        {        case etGT:          tok = etGE;          m_Value += ch;          break;        case etLT:          tok = etLE;          m_Value += ch;          break;        default:          ASSD(0);          input.unget();        }      }      else if( etLT==ch && etLT==tok)      {        tok = etShiftLeft;        m_Value += ch;      }      else if( etGT==ch && etGT==tok)      {        tok = etShiftRight;        m_Value += ch;      }      else      {        input.unget();      }      break;    case '`':      m_Value += ch;      while( input.get(ch) )      {        m_Value += ch;        if( '`'==ch )          break;      }      tok = etHCDVAR;      break;    default:      if( isalpha(ch) || '_'==ch )      {        m_Value += ch;        while( input.get(ch) )        {          if( isalpha(ch) || isdigit(ch) || '.'==ch || '_'==ch )          {}          else            break;          m_Value += ch;        }        tok = etTEXT;      }      else if( isdigit(ch) )      {        tok = etNUMBER;        m_Value += ch;        while( input.get(ch) )        {          if( isdigit(ch) || '.'==ch )          {            m_Value += ch;            continue;          }          break;        }      }      else      {        ASS(0);      }      input.unget();      break;    }    if( etTEXT==tok )    {      if( !IsSys( tok, m_Value ) )        IsConst( tok, m_Value );    }    return tok;  }  struct CSysID  {    LPSTR Name;    eToken_value ID;  };  static CSysID SysID[] =   {    "IF", etIF,     "ELSE", etELSE,    "OR", etOR,    "AND", etAND,  };  bool KHcdTranslator::IsSys( eToken_value &tok, std::string &szVal )  {    for( int i=0; i<_countof(SysID); i++ )    {      if( !_stricmp(szVal.c_str(), SysID[i].Name) )      {        tok = SysID[i].ID;        return true;      }    }    return false;  }  struct SNameByName  {    LPCSTR pN1;    eToken_value tok;  };  static SNameByName constVals[] =  {    {"true", etTRUE },    {"false", etFALSE },  };  bool KHcdTranslator::IsConst( eToken_value &tok, std::string &szVal )  {    for( int i=0; i<_countof(constVals); i++ )    {      if( !strcmp(szVal.c_str(), constVals[i].pN1) )      {        tok = constVals[i].tok;        return true;      }    }    return false;  }}